-- Soluciones (rubros) administrables desde el panel. Antes vivían en código
-- (packages/shared/src/config/rubros.ts), que queda como carga inicial.

CREATE TABLE "Category" (
    "id" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "summary" TEXT NOT NULL,
    "description" TEXT[],
    "subcategories" TEXT[],
    "faqs" JSONB NOT NULL DEFAULT '[]',
    "image" TEXT,
    "imageAlt" TEXT,
    "imagePosition" TEXT NOT NULL DEFAULT '50% 50%',
    "whatsappMessage" TEXT NOT NULL DEFAULT '',
    "seoTitle" TEXT,
    "seoDescription" TEXT,
    "order" INTEGER NOT NULL DEFAULT 0,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Category_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE INDEX "Category_active_order_idx" ON "Category"("active", "order");

INSERT INTO "Category" ("id", "slug", "name", "summary", "description", "subcategories", "faqs", "image", "imageAlt", "whatsappMessage", "seoTitle", "seoDescription", "order", "updatedAt") VALUES
  ('cat-materiales-electricos', 'materiales-electricos', 'Materiales eléctricos', 'Cables, caños, tableros y protecciones para cualquier instalación, de la casa a la obra.', ARRAY['Materiales Belgrano es una casa de materiales eléctricos en Godoy Cruz, Mendoza, con stock permanente de cables, cañerías, tableros, protecciones y accesorios para instalaciones domiciliarias e industriales. Vendemos a instaladores, empresas, constructoras y consumidor final, con entrega en 24 hs en Mendoza, San Juan y San Luis.', 'Trabajamos tres rangos de precio en la mayoría de las líneas, con proveedores que responden ante fallas y devoluciones. Si tenés una obra en marcha, pasanos el listado por WhatsApp y te cotizamos todo junto en minutos.']::text[], ARRAY['Cables y cañerías', 'Tableros y gabinetes', 'Electricidad domiciliaria: protecciones, llaves de luz, cajas', 'Electricidad industrial: protecciones de potencia, comando, señalización y control']::text[], '[{"question":"¿Venden materiales eléctricos por cantidad para obras?","answer":"Sí. Cotizamos listados completos de obra por WhatsApp y entregamos en el domicilio de la empresa o directamente en obra. Para pedidos grandes conviene avisar con 24 hs de anticipación, así preparamos todo y pedimos lo que no tengamos en stock."},{"question":"¿Qué marcas de cables y protecciones trabajan?","answer":"Trabajamos marcas reconocidas del mercado eléctrico argentino como Schneider Electric y Chint en protecciones, Kalop y Cables MH en cables, y Genrod y Conextube en canalizaciones. La lista completa está en la página de marcas, con el catálogo de cada fabricante."},{"question":"¿Hacen envíos de materiales eléctricos fuera de Mendoza?","answer":"Sí. Con transporte propio entregamos en 24 hs en Mendoza, San Juan y San Luis. Al resto del país enviamos por Andreani. Consultanos el costo y el plazo por WhatsApp antes de confirmar el pedido."}]'::jsonb, NULL, NULL, 'Hola, vengo de la web de Materiales Belgrano. Quiero consultar por materiales eléctricos.', 'Materiales eléctricos en Mendoza', 'Cables, cañerías, tableros, protecciones y accesorios eléctricos en Mendoza. Stock para instaladores, empresas y hogar. Entrega en 24 hs. Consultá por WhatsApp.', 0, CURRENT_TIMESTAMP),
  ('cat-iluminacion', 'iluminacion', 'Iluminación', 'Luminarias LED, de diseño y para proyectos, con exhibición encendida en el salón.', ARRAY['En Materiales Belgrano encontrás iluminación LED para proyectos profesionales, iluminación integrada para interiores, luminarias de exterior y jardín, y lámparas, tubos y tiras LED de alta rotación. Nuestro salón en Godoy Cruz, Mendoza, tiene exhibición de marcas de diseño como Leuk y 180° para que veas las luminarias encendidas antes de elegir.', 'Si estás armando un proyecto de iluminación para una obra, un local o una casa, traé el plano o mandanos fotos por WhatsApp: te ayudamos a elegir la solución y te la cotizamos completa.']::text[], ARRAY['Iluminación profesional y proyectos', 'Iluminación integrada interior', 'Iluminación de exterior y jardín', 'Lámparas, tubos y tiras LED', 'Iluminación solar']::text[], '[{"question":"¿Asesoran para elegir la iluminación de una casa o un local?","answer":"Sí. Nuestro equipo asesora en el salón o por WhatsApp sobre temperatura de color, potencia y tipo de luminaria según el ambiente. Para proyectos más grandes podés mandarnos el plano y te proponemos una solución completa con presupuesto."},{"question":"¿Qué marcas de iluminación venden?","answer":"Trabajamos Macroled para iluminación LED de alta rotación, Leuk y 180° para iluminación de diseño, y Litex para iluminación solar, entre otras. En la página de marcas está el catálogo de cada fabricante para que elijas el modelo exacto."},{"question":"¿Tienen stock de luminarias para entrega inmediata?","answer":"Sí. Mantenemos stock permanente de las líneas de mayor rotación: lámparas, tubos, paneles, tiras y luminarias de exterior. Los productos de diseño o de proyecto se piden al fabricante cuando no están en stock; te decimos el plazo al cotizar."}]'::jsonb, '/images/exhibicion-iluminacion-materiales-belgrano.webp', 'Iluminación en Materiales Belgrano', 'Hola, vengo de la web de Materiales Belgrano. Quiero consultar por iluminación.', 'Iluminación LED y de diseño en Mendoza', 'Iluminación profesional, interior, exterior y de diseño en Mendoza. Luminarias LED, tiras y lámparas. Marcas Macroled, Leuk y 180°. Consultá por WhatsApp.', 1, CURRENT_TIMESTAMP),
  ('cat-maquinas-y-herramientas', 'maquinas-y-herramientas', 'Máquinas y herramientas', 'Herramientas de mano, a batería y eléctricas, más instrumental de medición.', ARRAY['Materiales Belgrano vende máquinas y herramientas para instaladores electricistas, empresas y uso doméstico en Mendoza: herramientas de mano y consumibles, herramientas a batería y eléctricas, e instrumental de medición. Trabajamos marcas como Jadever y DCK, con respaldo del fabricante ante fallas.', 'Es una de las líneas que más crece en la casa porque el instalador encuentra en un mismo lugar el material y la herramienta para la obra.']::text[], ARRAY['Herramientas de mano y consumibles', 'Herramientas a batería', 'Herramientas eléctricas', 'Instrumental de medición']::text[], '[{"question":"¿Qué herramientas a batería tienen para electricistas?","answer":"Trabajamos líneas a batería de Jadever y DCK: atornilladores, taladros, amoladoras y kits para instaladores. Si buscás un modelo puntual, consultá por WhatsApp y te confirmamos stock y precio en el momento."},{"question":"¿Venden instrumental de medición como pinzas amperométricas y testers?","answer":"Sí. Tenemos pinzas amperométricas, multímetros, buscapolos y otros instrumentos de medición para instaladores. Consultá por WhatsApp el modelo que necesitás y te confirmamos disponibilidad."}]'::jsonb, NULL, NULL, 'Hola, vengo de la web de Materiales Belgrano. Quiero consultar por máquinas y herramientas.', 'Máquinas y herramientas para electricistas en Mendoza', 'Herramientas de mano, a batería y eléctricas, consumibles e instrumental de medición en Mendoza. Marcas Jadever y DCK. Stock para instaladores y empresas.', 2, CURRENT_TIMESTAMP),
  ('cat-dispositivos-smart', 'dispositivos-smart', 'Dispositivos smart', 'Tomas, interruptores y cerraduras que se manejan desde el celular.', ARRAY['En Materiales Belgrano vendemos dispositivos smart para el hogar y la empresa en Mendoza: accesorios de medición y control por wifi, cerraduras inteligentes y productos de automatización que se integran a la instalación eléctrica.', 'Es una línea en crecimiento: si tenés un proyecto de domótica o querés automatizar un ambiente, contanos qué necesitás por WhatsApp y te orientamos con lo que tenemos en stock.']::text[], ARRAY['Accesorios de medición y control wifi', 'Cerraduras inteligentes']::text[], '[{"question":"¿Qué dispositivos smart venden?","answer":"Vendemos accesorios de medición y control por wifi (tomas, interruptores y módulos inteligentes) y cerraduras smart. Son productos que se instalan sobre la instalación eléctrica existente y se manejan desde el celular. Consultá por WhatsApp los modelos disponibles."}]'::jsonb, NULL, NULL, 'Hola, vengo de la web de Materiales Belgrano. Quiero consultar por dispositivos smart.', 'Dispositivos smart y domótica en Mendoza', 'Dispositivos inteligentes wifi para el hogar y la empresa en Mendoza: medición y control, cerraduras smart y automatización. Consultá por WhatsApp.', 3, CURRENT_TIMESTAMP),
  ('cat-camaras-y-videovigilancia', 'camaras-y-videovigilancia', 'Cámaras y videovigilancia', 'Cámaras, videoporteros y grabadores para obras, comercios y casas.', ARRAY['Materiales Belgrano vende cámaras de seguridad, videoporteros y accesorios de videovigilancia en Mendoza, con la marca Uniview como línea principal. Hoy prácticamente toda obra lleva cámaras, así que el instalador encuentra en la casa el material eléctrico y el sistema de videovigilancia juntos.', 'Si estás instalando cámaras en una obra, un comercio o una casa, mandanos por WhatsApp qué necesitás cubrir y te cotizamos el kit completo.']::text[], ARRAY['Cámaras de seguridad', 'Videoporteros', 'Grabadores y accesorios']::text[], '[{"question":"¿Qué marca de cámaras de seguridad trabajan?","answer":"Trabajamos Uniview, una marca internacional de videovigilancia con cámaras IP, grabadores y accesorios para obras, comercios y hogares. Consultá por WhatsApp y te armamos el kit según la cantidad de cámaras y el tipo de instalación."},{"question":"¿Venden videoporteros?","answer":"Sí. Tenemos videoporteros para casas y edificios, además de cámaras y grabadores. Es una de las líneas que estamos impulsando este año, así que si no ves el modelo que buscás, consultanos y lo pedimos al fabricante."}]'::jsonb, NULL, NULL, 'Hola, vengo de la web de Materiales Belgrano. Quiero consultar por cámaras y videovigilancia.', 'Cámaras de seguridad y videovigilancia en Mendoza', 'Cámaras de seguridad, videoporteros y accesorios de videovigilancia en Mendoza. Marca Uniview. Para obras, comercios y hogares. Consultá por WhatsApp.', 4, CURRENT_TIMESTAMP);

-- Los slots de imagen de rubros pasan a ser la imagen de cada solución.
UPDATE "Category" c SET "image" = s."url", "imageAlt" = s."alt", "imagePosition" = COALESCE(s."position", '50% 50%')
FROM "ImageSlot" s WHERE s."key" = 'rubros.' || c."slug" || '.hero' AND s."url" <> '';
DELETE FROM "ImageSlot" WHERE "key" LIKE 'rubros.%';

-- La web la lee con la anon key: sólo las soluciones activas.
ALTER TABLE "Category" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "Category" FROM anon, authenticated;
GRANT SELECT ON TABLE "Category" TO anon;

CREATE POLICY "Public read active categories" ON "Category"
  FOR SELECT TO anon USING ("active" = true);
